package vn.smartfarm.iot.control;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.web.servlet.MockMvc;
import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=${SMARTFARM_TEST_DB_URL}","spring.flyway.schemas=telemetry_test","spring.flyway.default-schema=telemetry_test","smartfarm.mqtt.enabled=false","smartfarm.control.enabled=false","smartfarm.control.pump-fencing-enabled=false"})
@AutoConfigureMockMvc @EnabledIfEnvironmentVariable(named="SMARTFARM_TEST_DB_URL",matches=".+")
class PumpValveInterlockTest {
 @Autowired PumpService pump;@Autowired JdbcTemplate jdbc;@Autowired ObjectMapper mapper;@Autowired MockMvc mvc;
 Instant base;long commands,runs;@BeforeEach void setup(){jdbc.update("DELETE FROM pump_status");jdbc.update("DELETE FROM pump_state_history");base=Instant.now().minusSeconds(2);commands=count("pump_command");runs=count("watering_run");}
 @AfterEach void cleanup(){assertEquals(commands,count("pump_command"));assertEquals(runs,count("watering_run"));jdbc.update("DELETE FROM pump_status");jdbc.update("DELETE FROM pump_state_history");}
 long count(String table){return jdbc.queryForObject("SELECT COUNT(*) FROM "+table,Long.class);}
 ObjectNode packet(int sequence){var p=mapper.createObjectNode().put("schemaVersion",1).put("deviceId","PUMP01").put("bootId","84000000-0000-4000-8000-000000000001").put("sequence",sequence).put("timestamp",base.plusMillis(sequence).toString()).put("connection","ONLINE").put("reportedState","OFF").put("safetyLockout",false).put("stateReason","BOOT").putNull("activeCommandId");p.putObject("valveInterlock").put("version",1).put("enabled",true).put("dataSource","SIMULATOR").put("state","OPEN").putNull("fault");return p;}
 void receive(ObjectNode p)throws Exception{pump.receive("smartfarm/FARM001/PUMP01/status",mapper.writeValueAsBytes(p));}
 JsonNode stored(){return pump.storedValveInterlock(jdbc.queryForObject("SELECT valve_interlock::text FROM pump_status WHERE singleton=1",String.class))==null?null:mapper.valueToTree(pump.storedValveInterlock(jdbc.queryForObject("SELECT valve_interlock::text FROM pump_status WHERE singleton=1",String.class)));}
 ObjectNode fault(int seq){var p=packet(seq).put("safetyLockout",true).put("stateReason","VALVE_PROOF_LOST");((ObjectNode)p.get("valveInterlock")).put("fault","VALVE_PROOF_LOST").put("state","UNKNOWN");return p;}
 @Test void legacyStatusRemainsUnverifiedWithoutInventedMetadata()throws Exception{var p=packet(0);p.remove("valveInterlock");receive(p);assertNull(stored());mvc.perform(get("/api/v1/safety")).andExpect(status().isOk()).andExpect(jsonPath("$.relay.valveInterlock").isEmpty());}
 @Test void validProofIsStoredAndExposedAsDeviceReportWithoutDispatch()throws Exception{receive(packet(0));assertEquals("OPEN",stored().path("state").asText());mvc.perform(get("/api/v1/safety")).andExpect(status().isOk()).andExpect(jsonPath("$.relay.valveInterlock.dataSource").value("SIMULATOR"));}
 @Test void faultRequiresLockedOffAndIsKeptInStateHistory()throws Exception{receive(fault(0));assertEquals("VALVE_PROOF_LOST",pump.stateHistory().getFirst().stateReason());assertTrue(pump.status().safetyLockout());assertEquals("VALVE_PROOF_LOST",stored().path("fault").asText());assertThrows(Exception.class,()->receive(fault(1).put("safetyLockout",false)));assertThrows(Exception.class,()->receive(fault(1).put("reportedState","ON")));}
 @Test void malformedCapabilitiesCannotReplaceValidObservation()throws Exception{receive(packet(0));for(String field:List.of("version","enabled","dataSource","state","fault")){var p=packet(1);((ObjectNode)p.get("valveInterlock")).remove(field);assertThrows(Exception.class,()->receive(p));}var extra=packet(1);((ObjectNode)extra.get("valveInterlock")).put("extra",1);assertThrows(Exception.class,()->receive(extra));assertEquals(0,jdbc.queryForObject("SELECT sequence FROM pump_status",Integer.class));}
 @Test void wrongTypesPhysicalSourceAndUnknownFaultAreRejected()throws Exception{for(int i=0;i<6;i++){var p=packet(0);var f=(ObjectNode)p.get("valveInterlock");switch(i){case 0->f.put("enabled",false);case 1->f.put("version",2);case 2->f.put("dataSource","PHYSICAL");case 3->f.put("state","SAFE");case 4->f.put("fault","BAD");default->f.put("enabled","true");}assertThrows(Exception.class,()->receive(p));}assertEquals(0,count("pump_status"));}
 @Test void onRequiresOpenProofAndNoFaultOrLockout()throws Exception{receive(packet(0).put("reportedState","ON").put("stateReason","COMMAND_ON"));for(String state:List.of("UNKNOWN","CLOSED","CONFLICT")){var p=packet(1).put("reportedState","ON");((ObjectNode)p.get("valveInterlock")).put("state",state);assertThrows(Exception.class,()->receive(p));}assertThrows(Exception.class,()->receive(packet(1).put("reportedState","ON").put("safetyLockout",true)));}
 @Test void capabilityCannotDisappearWithinSameBoot()throws Exception{receive(packet(0));var p=packet(1);p.remove("valveInterlock");receive(p);assertEquals(0,jdbc.queryForObject("SELECT sequence FROM pump_status",Integer.class));assertNotNull(stored());}
 @Test void faultCannotClearWithoutExplicitReportedReset()throws Exception{receive(fault(0));receive(packet(1));assertEquals("VALVE_PROOF_LOST",stored().path("fault").asText());receive(packet(2).put("stateReason","LOCKOUT_RESET"));assertTrue(stored().path("fault").isNull());assertFalse(pump.status().safetyLockout());}
 @Test void restoredOpenContactsCanRemainLatchedAndBadResetIsRejected()throws Exception{var p=fault(0);((ObjectNode)p.get("valveInterlock")).put("state","OPEN");receive(p);assertTrue(pump.status().safetyLockout());var reset=packet(1).put("stateReason","LOCKOUT_RESET");((ObjectNode)reset.get("valveInterlock")).put("state","CLOSED");assertThrows(Exception.class,()->receive(reset));}
 @Test void newBootMayReportLegacyButCannotBorrowThePreviousProof()throws Exception{receive(fault(0));var p=packet(1).put("bootId","84000000-0000-4000-8000-000000000002");p.remove("valveInterlock");receive(p);assertNull(stored());}
 @Test void duplicateOrOldSequenceCannotRefreshReceiptOrCapability()throws Exception{receive(packet(1));var before=jdbc.queryForObject("SELECT row_to_json(s)::text FROM pump_status s",String.class);receive(packet(1));receive(fault(0));assertEquals(before,jdbc.queryForObject("SELECT row_to_json(s)::text FROM pump_status s",String.class));}
 @Test void faultReasonWithoutProofAndProofOnAckAreRejected()throws Exception{var p=fault(0);p.remove("valveInterlock");assertThrows(Exception.class,()->receive(p));assertThrows(Exception.class,()->pump.receive("smartfarm/FARM001/PUMP01/ack",mapper.writeValueAsBytes(packet(0))));}
 @Test void nativeEncoderStatusGoesThroughActualReceiver()throws Exception{try(var in=getClass().getResourceAsStream("/pump-valve-proof-packets.json")){assertNotNull(in);var frames=mapper.readTree(in);for(int i=0;i<frames.size();i++){var p=(ObjectNode)frames.get(i);p.put("timestamp",base.plusMillis(i).toString());receive(p);assertEquals(p.path("valveInterlock"),stored());}assertEquals("LOCKOUT_RESET",pump.stateHistory().getFirst().stateReason());}}
 @Test void safetyReadsDoNotChangeProofClocksOrCommands()throws Exception{receive(fault(0));var before=jdbc.queryForObject("SELECT row_to_json(s)::text FROM pump_status s",String.class);mvc.perform(get("/api/v1/safety")).andExpect(status().isOk());assertEquals(before,jdbc.queryForObject("SELECT row_to_json(s)::text FROM pump_status s",String.class));}
 @Test void proofMetadataCanCoexistWithTheExistingPumpFence()throws Exception{var p=fault(0);p.putObject("commandFence").put("version",1).put("lastOrdinal",0).put("restartRequired",false);receive(p);assertEquals(1,jdbc.queryForObject("SELECT fence_version FROM pump_status",Integer.class));assertEquals("VALVE_PROOF_LOST",stored().path("fault").asText());}
}
